mapper.select:

  and m.match_status != 'CANCELLED'
and m.season_id = #{seasonId}
and m.division_id = #{divisionId}
and m.match_status = #{matchStatus}
and m.publish_status = #{publishStatus}
and ls.submission_status = #{submissionStatus}
and m.match_status != 'FINISHED'
order by m.match_time desc, m.id desc


  and m.match_status != 'CANCELLED'
and m.season_id = #{seasonId}
and m.division_id = #{divisionId}
and m.match_status = #{status}
and m.match_status != 'FINISHED'

    and (ls.submission_status is null or ls.submission_status in ('DRAFT', 'REJECTED'))

order by m.match_time asc, m.id asc
